-- ── hr_crops.regrow_limit — the finite-perennial cap ─────────────────────
-- The column lives on the generated master catalogue (hr_crops); this ALTER
-- makes it exist on a database built by an older generator, and the UPDATE
-- fills the ONE farm-owned value from REGROW_LIMITS. 0 = non-regrow / legacy
-- infinite sentinel (unreachable on a regrowing crop — the assertion forbids it).
do $$
begin
  if to_regclass('public.hr_crops') is null then
    raise exception 'hr_crops absent — apply the master catalogue (gen-catalogues) first';
  end if;
end $$;
alter table public.hr_crops add column if not exists regrow_limit int not null default 0;

update public.hr_crops as k set regrow_limit = v.lim
  from (values
  ('carrot', 0),
  ('emberfruit', 4),
  ('goldenroot', 0),
  ('moonbloom', 0),
  ('potato', 0),
  ('pumpkin', 0),
  ('tomato', 4),
  ('turnip', 0),
  ('wheat', 0)
  ) as v(crop_id, lim)
 where k.crop_id = v.crop_id and k.regrow_limit is distinct from v.lim;

-- ── the three farm-gate catalogues ───────────────────────────────────────
do $$
begin
  if to_regclass('public.hr_crop_plot_tier') is null then
    create table public.hr_crop_plot_tier (
      crop_id   text primary key,
      plot_tier int  not null check (plot_tier between 1 and 5)
    );
    alter table public.hr_crop_plot_tier enable row level security;
  end if;
  if to_regclass('public.hr_plot_tier') is null then
    create table public.hr_plot_tier (
      plot_level int primary key check (plot_level between 1 and 5)
    );
    alter table public.hr_plot_tier enable row level security;
  end if;
  if to_regclass('public.hr_farm_yield_perk') is null then
    create table public.hr_farm_yield_perk (
      perk_key   text primary key,
      farm_yield int  not null check (farm_yield >= 0)
    );
    alter table public.hr_farm_yield_perk enable row level security;
  end if;
end $$;

-- Read-only catalogues: readable by everyone signed in, written by NO client.
do $$
declare t text;
begin
  foreach t in array array['hr_crop_plot_tier','hr_plot_tier','hr_farm_yield_perk'] loop
    execute format('revoke all on public.%I from public, anon, authenticated, service_role', t);
    execute format('grant select on public.%I to anon, authenticated, service_role', t);
    execute format('drop policy if exists %I on public.%I', t || '_sel', t);
    execute format('create policy %I on public.%I for select using (true)', t || '_sel', t);
  end loop;
end $$;

truncate table public.hr_crop_plot_tier;
insert into public.hr_crop_plot_tier (crop_id, plot_tier) values
  ('carrot', 2),
  ('emberfruit', 5),
  ('goldenroot', 4),
  ('moonbloom', 5),
  ('potato', 3),
  ('pumpkin', 4),
  ('tomato', 3),
  ('turnip', 1),
  ('wheat', 2);

alter table public.hr_plot_tier add column if not exists gold_cost      bigint not null default 0;
alter table public.hr_plot_tier add column if not exists req_farm_level int    not null default 1;
-- THE DEED'S PRICE COLUMN GOES (lane/c-dead-plot-deed, 2026-11-07), never under a reader: a body that still
-- read it would fail every plot upgrade from this apply on.
do $$
declare v_fns text;
begin
  select string_agg(p.oid::regprocedure::text, ', ' order by p.oid::regprocedure::text) into v_fns
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and strpos(p.prosrc, 'deed_cost') > 0;
  if v_fns is not null then
    raise exception 'PRECONDITION: % still read(s) hr_plot_tier.deed_cost: apply 2027-03-22-dead-plot-deed.sql first', v_fns;
  end if;
end $$;
alter table public.hr_plot_tier drop column if exists deed_cost;
truncate table public.hr_plot_tier;
insert into public.hr_plot_tier (plot_level, gold_cost, req_farm_level) values
  (1, 0, 1),
  (2, 500, 5),
  (3, 5000, 25),
  (4, 25000, 45),
  (5, 100000, 70);

truncate table public.hr_farm_yield_perk;
insert into public.hr_farm_yield_perk (perk_key, farm_yield) values
  ('garden:1', 0),
  ('garden:2', 0),
  ('garden:3', 0),
  ('garden:4', 0),
  ('garden:5', 0),
  ('companion:bunny', 1),
  ('companion:squirrel', 1);

-- ── Self-verification ────────────────────────────────────────────────────
do $$
declare v_n int; v_bad int;
begin
  select count(*) into v_n from public.hr_crop_plot_tier;
  if v_n <> 9 then raise exception 'hr_crop_plot_tier has % rows, expected 9', v_n; end if;
  select count(*) into v_n from public.hr_plot_tier;
  if v_n <> 5 then raise exception 'hr_plot_tier has % rows, expected 5', v_n; end if;
  select count(*) into v_n from public.hr_farm_yield_perk;
  if v_n <> 7 then raise exception 'hr_farm_yield_perk has % rows, expected 7', v_n; end if;

  -- Every regrowing crop MUST carry a finite (>0) regrow_limit (no infinite
  -- perennial — arming the harvest RPC otherwise reverts the b420/b428 ruling).
  select count(*) into v_bad from public.hr_crops where regrows and regrow_limit <= 0;
  if v_bad > 0 then raise exception '% regrowing crop(s) have no finite regrow_limit', v_bad; end if;

  -- Every gated crop must be a real hr_crops row (the plant RPC joins them).
  select count(*) into v_bad from public.hr_crop_plot_tier c
    where not exists (select 1 from public.hr_crops k where k.crop_id = c.crop_id);
  if v_bad > 0 then raise exception '% plot-tier crops are absent from hr_crops', v_bad; end if;

  -- Level 1 must be free and ungated; the deed's price column is gone; no client write policy may exist on a catalogue.
  if not exists (select 1 from public.hr_plot_tier where plot_level = 1 and gold_cost = 0 and req_farm_level = 1) then
    raise exception 'plot level 1 must be free and ungated';
  end if;
  if exists (select 1 from information_schema.columns
              where table_schema = 'public' and table_name = 'hr_plot_tier' and column_name = 'deed_cost') then
    raise exception 'hr_plot_tier still carries deed_cost';
  end if;
  -- Every paid tier carries its gold price and farming gate (R1: never the defaults).
  if not exists (select 1 from public.hr_plot_tier where plot_level = 2 and gold_cost = 500 and req_farm_level = 5) then
    raise exception 'plot level 2 is not priced at 500 gold / farming 5'; end if;
  if not exists (select 1 from public.hr_plot_tier where plot_level = 3 and gold_cost = 5000 and req_farm_level = 25) then
    raise exception 'plot level 3 is not priced at 5000 gold / farming 25'; end if;
  if not exists (select 1 from public.hr_plot_tier where plot_level = 4 and gold_cost = 25000 and req_farm_level = 45) then
    raise exception 'plot level 4 is not priced at 25000 gold / farming 45'; end if;
  if not exists (select 1 from public.hr_plot_tier where plot_level = 5 and gold_cost = 100000 and req_farm_level = 70) then
    raise exception 'plot level 5 is not priced at 100000 gold / farming 70'; end if;
  select count(*) into v_bad from public.hr_plot_tier where plot_level > 1 and (gold_cost <= 0 or req_farm_level <= 1);
  if v_bad > 0 then raise exception '% plot tier(s) above 1 are free or ungated', v_bad; end if;
  select count(*) into v_bad from pg_policies
    where schemaname = 'public'
      and tablename in ('hr_crop_plot_tier','hr_plot_tier','hr_farm_yield_perk')
      and cmd in ('INSERT','UPDATE','DELETE','ALL');
  if v_bad > 0 then raise exception '% write policies on the farm catalogues', v_bad; end if;
end $$;
